ALTER TABLE public.venues ADD COLUMN IF NOT EXISTS latitude double precision, ADD COLUMN IF NOT EXISTS longitude double precision;
ALTER TABLE public.hr_shifts ADD COLUMN IF NOT EXISTS venue_id uuid REFERENCES public.venues(id), ADD COLUMN IF NOT EXISTS role text, ADD COLUMN IF NOT EXISTS hours_confirmed_by uuid, ADD COLUMN IF NOT EXISTS hours_confirmed_at timestamptz;
ALTER TABLE public.hr_attendance ADD COLUMN IF NOT EXISTS venue_id uuid REFERENCES public.venues(id), ADD COLUMN IF NOT EXISTS break_minutes integer NOT NULL DEFAULT 0 CHECK (break_minutes BETWEEN 0 AND 1440), ADD COLUMN IF NOT EXISTS confirmed_by uuid, ADD COLUMN IF NOT EXISTS confirmed_at timestamptz;
CREATE FUNCTION public.rota_manager(t uuid,v uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.people_access(t,u) AND EXISTS(SELECT 1 FROM public.venues WHERE id=v AND tenant_id=t AND is_active) AND (public.user_has_venue(u,v) OR public.people_owner(t,u) OR public.is_super_admin(u)) AND NOT EXISTS(SELECT 1 FROM public.user_page_permissions WHERE user_id=u AND tenant_id=t AND page_key='people' AND (NOT can_access OR authority='view_only')) $$;
REVOKE ALL ON FUNCTION public.rota_manager(uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rota_manager(uuid,uuid,uuid) TO authenticated,service_role;
CREATE TABLE public.hr_rota_weeks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),venue_id uuid NOT NULL REFERENCES public.venues(id),week_start date NOT NULL CHECK(extract(isodow from week_start)=1),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent')),sent_by uuid,sent_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,venue_id,week_start));
GRANT SELECT,INSERT,UPDATE ON public.hr_rota_weeks TO authenticated; GRANT ALL ON public.hr_rota_weeks TO service_role; ALTER TABLE public.hr_rota_weeks ENABLE ROW LEVEL SECURITY;
CREATE POLICY rota_week_read ON public.hr_rota_weeks FOR SELECT TO authenticated USING(public.people_access(tenant_id,auth.uid()) AND (public.user_has_venue(auth.uid(),venue_id) OR public.people_owner(tenant_id,auth.uid()) OR public.is_super_admin(auth.uid())));
CREATE POLICY rota_week_write ON public.hr_rota_weeks FOR ALL TO authenticated USING(public.rota_manager(tenant_id,venue_id,auth.uid())) WITH CHECK(public.rota_manager(tenant_id,venue_id,auth.uid()));
CREATE TABLE public.hr_swap_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),shift_id uuid NOT NULL REFERENCES public.hr_shifts(id),replacement_employee_id uuid NOT NULL REFERENCES public.hr_employees(id),requested_by uuid NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),decided_by uuid,decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_swap_requests TO authenticated; GRANT ALL ON public.hr_swap_requests TO service_role; ALTER TABLE public.hr_swap_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY swap_read ON public.hr_swap_requests FOR SELECT TO authenticated USING(public.people_access(tenant_id,auth.uid()) OR requested_by=auth.uid() AND public.user_has_tenant(auth.uid(),tenant_id));
CREATE FUNCTION public.rota_shift_scope(t uuid,e uuid,v uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.people_person_access(t,e,u) AND (v IS NULL OR public.rota_manager(t,v,u)) $$;
REVOKE ALL ON FUNCTION public.rota_shift_scope(uuid,uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rota_shift_scope(uuid,uuid,uuid,uuid) TO authenticated,service_role;
CREATE POLICY rota_shift_write_restriction ON public.hr_shifts AS RESTRICTIVE FOR ALL TO authenticated USING(public.rota_shift_scope(tenant_id,employee_id,venue_id,auth.uid()) OR EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.id=employee_id AND e.tenant_id=hr_shifts.tenant_id AND e.user_id=auth.uid())) WITH CHECK(public.rota_shift_scope(tenant_id,employee_id,venue_id,auth.uid()));
CREATE POLICY rota_attendance_restriction ON public.hr_attendance AS RESTRICTIVE FOR ALL TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()) OR EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.id=employee_id AND e.tenant_id=hr_attendance.tenant_id AND e.user_id=auth.uid())) WITH CHECK(public.people_person_access(tenant_id,employee_id,auth.uid()));
CREATE FUNCTION public.rota_edit(t uuid,v uuid,changes jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE p jsonb; sid uuid; e uuid; d date; typ text; st time; en time; b integer; terms jsonb; BEGIN
IF NOT public.rota_manager(t,v,auth.uid()) OR NOT (public.people_effective_settings(t,v)->>'rota')::boolean THEN RAISE EXCEPTION 'Rota changes are not available for this venue'; END IF;
IF jsonb_typeof(changes)<>'array' OR jsonb_array_length(changes)>500 THEN RAISE EXCEPTION 'Invalid rota changes'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||v::text,0));
FOR p IN SELECT value FROM jsonb_array_elements(changes) LOOP
 e:=(p->>'employee_id')::uuid;d:=(p->>'shift_date')::date;sid:=NULLIF(p->>'id','')::uuid;
 IF NOT public.people_person_access(t,e,auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=e AND tenant_id=t) THEN RAISE EXCEPTION 'Person access required'; END IF;
 IF sid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_shifts WHERE id=sid AND tenant_id=t AND employee_id=e AND shift_date=d AND (venue_id=v OR venue_id IS NULL)) THEN RAISE EXCEPTION 'Shift changed; reload the rota'; END IF;
 IF p->>'remove'='true' THEN DELETE FROM public.hr_shifts WHERE id=sid AND tenant_id=t; ELSE
 typ:=COALESCE(p->>'shift_type','regular');st:=COALESCE(p->>'start_time','00:00')::time;en:=COALESCE(p->>'end_time','00:00')::time;b:=COALESCE((p->>'break_minutes')::integer,0);
 IF typ NOT IN ('regular','RD','AL','SL','SH','NPL') OR b<0 OR b>1440 OR (typ='regular' AND (st=en OR b>=extract(epoch from (CASE WHEN en<st THEN en-st+interval '24 hours' ELSE en-st END))/60)) THEN RAISE EXCEPTION 'Check shift times and break'; END IF;
 IF typ='regular' AND EXISTS(SELECT 1 FROM public.hr_leave_requests WHERE tenant_id=t AND employee_id=e AND status='approved' AND d BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'This person is on approved leave'; END IF;
 IF sid IS NULL THEN INSERT INTO public.hr_shifts(tenant_id,venue_id,employee_id,shift_date,start_time,end_time,break_minutes,shift_type,role,status) VALUES(t,v,e,d,st,en,b,typ,NULLIF(p->>'role',''),'scheduled'); ELSE UPDATE public.hr_shifts SET start_time=st,end_time=en,break_minutes=b,shift_type=typ,role=NULLIF(p->>'role',''),venue_id=v WHERE id=sid AND tenant_id=t; END IF;
 END IF;
 INSERT INTO public.hr_rota_weeks(tenant_id,venue_id,week_start,status) VALUES(t,v,d-(extract(isodow from d)::integer-1),'draft') ON CONFLICT(tenant_id,venue_id,week_start) DO UPDATE SET status='draft',updated_at=now();
END LOOP; END $$;
REVOKE ALL ON FUNCTION public.rota_edit(uuid,uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rota_edit(uuid,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.rota_send(t uuid,v uuid,w date) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT public.rota_manager(t,v,auth.uid()) OR NOT (public.people_effective_settings(t,v)->>'rota')::boolean THEN RAISE EXCEPTION 'Rota changes unavailable';END IF;INSERT INTO public.hr_rota_weeks(tenant_id,venue_id,week_start,status,sent_by,sent_at) VALUES(t,v,w,'sent',auth.uid(),now()) ON CONFLICT(tenant_id,venue_id,week_start) DO UPDATE SET status='sent',sent_by=auth.uid(),sent_at=now(),updated_at=now();END $$;
REVOKE ALL ON FUNCTION public.rota_send(uuid,uuid,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_send(uuid,uuid,date) TO authenticated;
CREATE FUNCTION public.rota_clock_context(t uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.hr_employees;v uuid;d date:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date; BEGIN IF auth.uid() IS NULL OR NOT public.user_has_tenant(auth.uid(),t) OR EXISTS(SELECT 1 FROM public.user_access_control WHERE user_id=auth.uid() AND tenant_id=t AND status='disabled') THEN RAISE EXCEPTION 'Sign in to your company';END IF;IF (SELECT count(*) FROM public.hr_employees WHERE tenant_id=t AND user_id=auth.uid() AND status IN ('active','on_leave') AND hire_date<=d AND (end_date IS NULL OR end_date>d))<>1 THEN RETURN jsonb_build_object('unlinked',true);END IF; SELECT * INTO e FROM public.hr_employees WHERE tenant_id=t AND user_id=auth.uid() AND status IN ('active','on_leave') AND hire_date<=d AND (end_date IS NULL OR end_date>d);v:=COALESCE(NULLIF(public.people_terms_at(t,e.id,d)->>'venue_id','')::uuid,e.venue_id);RETURN jsonb_build_object('employee_id',e.id,'name',e.first_name||' '||e.last_name,'venue_id',v,'venue',(SELECT name FROM public.venues WHERE id=v AND tenant_id=t),'settings',public.people_effective_settings(t,v),'shift',(SELECT to_jsonb(s) FROM public.hr_shifts s WHERE tenant_id=t AND employee_id=e.id AND shift_date=d AND shift_type='regular' ORDER BY start_time LIMIT 1),'attendance',(SELECT to_jsonb(a) FROM public.hr_attendance a WHERE tenant_id=t AND employee_id=e.id AND (clock_out IS NULL AND clock_in IS NOT NULL OR date=d) ORDER BY clock_in DESC NULLS LAST LIMIT 1));END $$;
REVOKE ALL ON FUNCTION public.rota_clock_context(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_clock_context(uuid) TO authenticated;
CREATE FUNCTION public.rota_clock(t uuid,action text,lat double precision DEFAULT NULL,lng double precision DEFAULT NULL,accuracy double precision DEFAULT NULL,b integer DEFAULT 0) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ctx jsonb;e uuid;v uuid;s jsonb;a public.hr_attendance;vl double precision;vn double precision;distance double precision;d date:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date; BEGIN ctx:=public.rota_clock_context(t);e:=(ctx->>'employee_id')::uuid;v:=(ctx->>'venue_id')::uuid;s:=ctx->'settings';IF e IS NULL OR v IS NULL THEN RAISE EXCEPTION 'Ask your manager to link your account and venue';END IF;IF s->>'clock_in'='off' THEN RAISE EXCEPTION 'Clock-in is switched off for your venue';END IF;IF action NOT IN ('in','out') OR b<0 OR b>1440 THEN RAISE EXCEPTION 'Invalid clock action';END IF;
IF s->>'clock_in'='venue_phone' THEN SELECT latitude,longitude INTO vl,vn FROM public.venues WHERE id=v AND tenant_id=t AND is_active;IF vl IS NULL OR vn IS NULL THEN RAISE EXCEPTION 'Your venue location has not been saved; ask your manager';END IF;IF lat IS NULL OR lng IS NULL OR accuracy IS NULL OR lat NOT BETWEEN -90 AND 90 OR lng NOT BETWEEN -180 AND 180 OR accuracy NOT BETWEEN 0 AND 150 THEN RAISE EXCEPTION 'Allow a precise location reading at the venue';END IF;distance:=6371000*2*asin(sqrt(least(1.0,power(sin(radians(lat-vl)/2),2)+cos(radians(vl))*cos(radians(lat))*power(sin(radians(lng-vn)/2),2))));IF distance>150 THEN RAISE EXCEPTION 'You are too far from the venue to clock in or out';END IF;END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||e::text,0));SELECT * INTO a FROM public.hr_attendance WHERE tenant_id=t AND employee_id=e AND clock_in IS NOT NULL AND clock_out IS NULL ORDER BY clock_in DESC LIMIT 1 FOR UPDATE;
IF action='in' THEN IF a.id IS NOT NULL THEN RAISE EXCEPTION 'You are already clocked in';END IF;INSERT INTO public.hr_attendance(tenant_id,employee_id,venue_id,date,clock_in,status) VALUES(t,e,v,d,now(),'present');ELSE IF a.id IS NULL THEN RAISE EXCEPTION 'Clock in first';END IF;IF b>extract(epoch from(now()-a.clock_in))/60 THEN RAISE EXCEPTION 'Break cannot exceed time clocked in';END IF;UPDATE public.hr_attendance SET clock_out=now(),break_minutes=b,hours_worked=greatest(0,extract(epoch from(now()-a.clock_in))/3600-b/60.0),confirmed_by=NULL,confirmed_at=NULL WHERE id=a.id;END IF;END $$;
REVOKE ALL ON FUNCTION public.rota_clock(uuid,text,double precision,double precision,double precision,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_clock(uuid,text,double precision,double precision,double precision,integer) TO authenticated;
CREATE FUNCTION public.rota_confirm_hours(t uuid,v uuid,d date,rows jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE p jsonb;a public.hr_attendance;BEGIN IF NOT public.rota_manager(t,v,auth.uid()) OR public.people_effective_settings(t,v)->>'clock_in'='off' THEN RAISE EXCEPTION 'Hours confirmation unavailable';END IF;IF jsonb_typeof(rows)<>'array' THEN RAISE EXCEPTION 'Invalid hours';END IF;FOR p IN SELECT value FROM jsonb_array_elements(rows) LOOP SELECT * INTO a FROM public.hr_attendance WHERE id=(p->>'id')::uuid AND tenant_id=t AND date=d AND venue_id=v FOR UPDATE;IF a.id IS NULL OR a.clock_out IS NULL OR a.updated_at<>(p->>'updated_at')::timestamptz THEN RAISE EXCEPTION 'Hours changed; reload before confirming';END IF;UPDATE public.hr_attendance SET confirmed_by=auth.uid(),confirmed_at=now() WHERE id=a.id;UPDATE public.hr_shifts SET hours_confirmed_by=auth.uid(),hours_confirmed_at=now() WHERE tenant_id=t AND employee_id=a.employee_id AND shift_date=d AND (venue_id=v OR venue_id IS NULL);END LOOP;END $$;
REVOKE ALL ON FUNCTION public.rota_confirm_hours(uuid,uuid,date,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_confirm_hours(uuid,uuid,date,jsonb) TO authenticated;
CREATE FUNCTION public.rota_leave(t uuid,e uuid,k text,d date,last_day date,request_id uuid DEFAULT NULL,yes boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid;lt public.hr_leave_types;lr public.hr_leave_requests;bal public.hr_leave_balances;n numeric;used numeric;remaining numeric;uid uuid:=auth.uid();BEGIN v:=COALESCE(NULLIF(public.people_terms_at(t,e,d)->>'venue_id','')::uuid,(SELECT venue_id FROM public.hr_employees WHERE id=e AND tenant_id=t));IF NOT public.rota_manager(t,v,uid) OR NOT public.people_person_access(t,e,uid) OR NOT (public.people_effective_settings(t,v)->>'leave_requests')::boolean THEN RAISE EXCEPTION 'Leave approval unavailable';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||e::text,1));
IF request_id IS NOT NULL THEN SELECT * INTO lr FROM public.hr_leave_requests WHERE id=request_id AND tenant_id=t AND employee_id=e FOR UPDATE;IF lr.id IS NULL OR lr.status<>'pending' THEN RAISE EXCEPTION 'Request already decided';END IF;d:=lr.start_date;last_day:=lr.end_date;SELECT * INTO lt FROM public.hr_leave_types WHERE id=lr.leave_type_id AND tenant_id=t;ELSE SELECT * INTO lt FROM public.hr_leave_types WHERE tenant_id=t AND is_active AND lower(name)=lower(k) LIMIT 1;IF lt.id IS NULL AND k='Unpaid' THEN INSERT INTO public.hr_leave_types(tenant_id,name,is_paid,default_days_per_year,is_active) VALUES(t,'Unpaid',false,0,true) RETURNING * INTO lt;END IF;END IF;
IF lt.id IS NULL OR d>last_day OR last_day-d>365 OR extract(year from d)<>extract(year from last_day) THEN RAISE EXCEPTION 'Choose valid leave dates within one year';END IF;n:=last_day-d+1;
IF yes THEN SELECT * INTO bal FROM public.hr_leave_balances WHERE tenant_id=t AND employee_id=e AND leave_type_id=lt.id AND year=extract(year from d) ORDER BY id LIMIT 1 FOR UPDATE;
IF lt.is_paid THEN IF bal.id IS NULL THEN RAISE EXCEPTION 'No leave balance recorded; review this person first';END IF;remaining:=COALESCE(bal.carried_forward,0)+bal.total_days+COALESCE(bal.adjustments,0)-bal.used_days;IF remaining<n THEN RAISE EXCEPTION 'Not enough leave balance (% days available)',remaining;END IF;UPDATE public.hr_leave_balances SET used_days=used_days+n,remaining_days=remaining-n WHERE id=bal.id;END IF;
IF EXISTS(SELECT 1 FROM public.hr_leave_requests WHERE tenant_id=t AND employee_id=e AND status='approved' AND start_date<=last_day AND end_date>=d) THEN RAISE EXCEPTION 'Leave overlaps approved leave';END IF;END IF;
IF request_id IS NULL THEN INSERT INTO public.hr_leave_requests(tenant_id,employee_id,leave_type_id,start_date,end_date,days,status,approved_by,approved_at) VALUES(t,e,lt.id,d,last_day,n,CASE WHEN yes THEN 'approved' ELSE 'rejected' END,uid,now());ELSE UPDATE public.hr_leave_requests SET status=CASE WHEN yes THEN 'approved' ELSE 'rejected' END,approved_by=uid,approved_at=now(),days=n WHERE id=lr.id;END IF;
IF yes THEN UPDATE public.hr_shifts SET shift_type=CASE WHEN lower(lt.name) LIKE '%annual%' THEN 'AL' WHEN lower(lt.name) LIKE '%sick%' THEN 'SL' WHEN lower(lt.name) LIKE '%statutory%' THEN 'SH' ELSE 'NPL' END WHERE tenant_id=t AND employee_id=e AND shift_date BETWEEN d AND last_day;UPDATE public.hr_rota_weeks SET status='draft',updated_at=now() WHERE tenant_id=t AND venue_id=v AND week_start<=last_day AND week_start+6>=d;END IF;END $$;
REVOKE ALL ON FUNCTION public.rota_leave(uuid,uuid,text,date,date,uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_leave(uuid,uuid,text,date,date,uuid,boolean) TO authenticated;
CREATE FUNCTION public.rota_swap(t uuid,sid uuid,replacement uuid,request_id uuid DEFAULT NULL,yes boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.hr_shifts;v uuid;r public.hr_swap_requests;BEGIN IF request_id IS NOT NULL THEN SELECT * INTO r FROM public.hr_swap_requests WHERE id=request_id AND tenant_id=t FOR UPDATE;IF r.id IS NULL OR r.status<>'pending' THEN RAISE EXCEPTION 'Swap already decided';END IF;sid:=r.shift_id;replacement:=r.replacement_employee_id;END IF;SELECT * INTO s FROM public.hr_shifts WHERE id=sid AND tenant_id=t FOR UPDATE;v:=COALESCE(s.venue_id,(SELECT venue_id FROM public.hr_employees WHERE id=s.employee_id AND tenant_id=t));IF s.id IS NULL OR NOT public.rota_manager(t,v,auth.uid()) OR NOT public.people_person_access(t,replacement,auth.uid()) OR NOT (public.people_effective_settings(t,v)->>'rota')::boolean THEN RAISE EXCEPTION 'Swap unavailable';END IF;
IF yes THEN IF NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=replacement AND tenant_id=t AND status IN ('active','on_leave') AND hire_date<=s.shift_date AND (end_date IS NULL OR end_date>s.shift_date) AND COALESCE(NULLIF(public.people_terms_at(t,replacement,s.shift_date)->>'venue_id','')::uuid,venue_id)=v) OR EXISTS(SELECT 1 FROM public.hr_shifts WHERE tenant_id=t AND employee_id=replacement AND shift_date=s.shift_date AND shift_type='regular') OR EXISTS(SELECT 1 FROM public.hr_leave_requests WHERE tenant_id=t AND employee_id=replacement AND status='approved' AND s.shift_date BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'Cover is no longer available';END IF;UPDATE public.hr_shifts SET employee_id=replacement,venue_id=v WHERE id=s.id;UPDATE public.hr_rota_weeks SET status='draft',updated_at=now() WHERE tenant_id=t AND venue_id=v AND week_start=s.shift_date-(extract(isodow from s.shift_date)::integer-1);END IF;
IF request_id IS NOT NULL THEN UPDATE public.hr_swap_requests SET status=CASE WHEN yes THEN 'approved' ELSE 'rejected' END,decided_by=auth.uid(),decided_at=now() WHERE id=r.id;END IF;END $$;
REVOKE ALL ON FUNCTION public.rota_swap(uuid,uuid,uuid,uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_swap(uuid,uuid,uuid,uuid,boolean) TO authenticated;
CREATE FUNCTION public.rota_request_swap(t uuid,sid uuid,replacement uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.hr_shifts;v uuid;r uuid;BEGIN SELECT * INTO s FROM public.hr_shifts WHERE id=sid AND tenant_id=t;v:=COALESCE(s.venue_id,(SELECT venue_id FROM public.hr_employees WHERE id=s.employee_id AND tenant_id=t));IF NOT public.user_has_tenant(auth.uid(),t) OR NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=s.employee_id AND tenant_id=t AND user_id=auth.uid()) OR NOT (public.people_effective_settings(t,v)->>'rota')::boolean OR NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=replacement AND tenant_id=t AND venue_id=v AND status='active') THEN RAISE EXCEPTION 'Swap request unavailable';END IF;INSERT INTO public.hr_swap_requests(tenant_id,shift_id,replacement_employee_id,requested_by) VALUES(t,sid,replacement,auth.uid()) RETURNING id INTO r;RETURN r;END $$;
REVOKE ALL ON FUNCTION public.rota_request_swap(uuid,uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_request_swap(uuid,uuid,uuid) TO authenticated;
CREATE FUNCTION public.rota_save_location(t uuid,v uuid,lat double precision,lng double precision) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.people_access(t,auth.uid()) OR NOT public.has_role(auth.uid(),'admin') OR NOT EXISTS(SELECT 1 FROM public.venues WHERE id=v AND tenant_id=t) OR lat NOT BETWEEN -90 AND 90 OR lng NOT BETWEEN -180 AND 180 OR lat IS NULL OR lng IS NULL THEN RAISE EXCEPTION 'Admin and valid venue coordinates required';END IF;UPDATE public.venues SET latitude=lat,longitude=lng WHERE id=v AND tenant_id=t;END $$;
REVOKE ALL ON FUNCTION public.rota_save_location(uuid,uuid,double precision,double precision) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_save_location(uuid,uuid,double precision,double precision) TO authenticated;